You are implementing features for a Blazor Web App (Interactive Auto, Global, with Individual auth) that tracks shipments for a logistics company. The project is already scaffolded at `/tmp/sv-3c982e6e8e414692ad59bafff52f2991/ShipmentTracker/`.

## Project Structure
- **ShipmentTracker/** (server project) — hosts app, APIs, EF Core, Identity
- **ShipmentTracker.Client/** (client project) — all interactive components, pages, service interfaces

## Architecture Rules (Auto mode)
- All interactive components and pages MUST go in the `.Client` project
- No direct DB access from `.Client` — use HTTP APIs
- Define service interfaces in `.Client`, implement with HttpClient there
- Implement server-side services using direct data access in the server project
- Register matching services in both `Program.cs` files
- Expose data through minimal API endpoints in server `Program.cs`
- Apply `[Authorize]` on pages and `.RequireAuthorization()` on API endpoints

## What to Implement

### 1. Remove Template Pages
Delete these files from `ShipmentTracker.Client/Pages/`:
- `Counter.razor`
- `Weather.razor`

Keep `Home.razor`, `Auth.razor`, and `NotFound.razor`.

### 2. Shared Models (in `.Client` project)
Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string CustomerEmail { get; set; } = string.Empty;
    public double WeightKg { get; set; }
    public string Notes { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed,
    Returned
}
```

### 3. Service Interface (in `.Client` project)
Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment?> GetShipmentByIdAsync(int id);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Client-Side Implementation (HttpClient-based, in `.Client` project)
Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync() =>
        await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber) =>
        await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");

    public async Task<Shipment?> GetShipmentByIdAsync(int id) =>
        await http.GetFromJsonAsync<Shipment?>($"api/shipments/{id}");

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status) =>
        await http.PutAsJsonAsync($"api/shipments/{id}/status", status);
}
```

### 5. Server-Side EF Core Entity and DbContext
Create `ShipmentTracker/Data/ShipmentEntity.cs`:
```csharp
namespace ShipmentTracker.Data;

using ShipmentTracker.Client.Models;

public class ShipmentEntity
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string CustomerEmail { get; set; } = string.Empty;
    public double WeightKg { get; set; }
    public string Notes { get; set; } = string.Empty;
}
```

Modify the existing `ApplicationDbContext` (in `ShipmentTracker/Data/ApplicationDbContext.cs`) to add:
```csharp
public DbSet<ShipmentEntity> Shipments => Set<ShipmentEntity>();
```

### 6. Server-Side Service Implementation
Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync() =>
        await db.Shipments.Select(e => ToModel(e)).ToListAsync();

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : ToModel(entity);
    }

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
    {
        var entity = await db.Shipments.FindAsync(id);
        return entity is null ? null : ToModel(entity);
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is not null)
        {
            entity.Status = status;
            if (status == ShipmentStatus.Delivered)
                entity.ActualDelivery = DateTime.UtcNow;
            await db.SaveChangesAsync();
        }
    }

    private static Shipment ToModel(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        ActualDelivery = e.ActualDelivery,
        RecipientName = e.RecipientName,
        CustomerEmail = e.CustomerEmail,
        WeightKg = e.WeightKg,
        Notes = e.Notes
    };
}
```

