    private List<Shipment>? shipments;
    private string searchText = "";
    private string statusFilter = "";

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(searchText)
                || s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase)
                || s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            && (string.IsNullOrEmpty(statusFilter)
                || s.Status.ToString() == statusFilter));

    protected override async Task OnInitializedAsync()
    {
        await RefreshAsync();
    }

    private async Task RefreshAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatusAsync(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            await RefreshAsync();
        }
    }

