            await db.SaveChangesAsync();
        }
    }

    private static Shipment ToModel(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        ActualDelivery = e.ActualDelivery,
        RecipientName = e.RecipientName,
        CustomerEmail = e.CustomerEmail,
        WeightKg = e.WeightKg,
        Notes = e.Notes
    };
}

@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>🚚 Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking # or destination..."
               @bind="searchText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-secondary w-100" @onclick="RefreshAsync">🔄 Refresh</button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <div class="alert alert-info">No shipments match your filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Weight (kg)</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>@s.WeightKg</td>
                        <td>
                            <select class="form-select form-select-sm" value="@s.Status"
                                    @onchange="e => UpdateStatusAsync(s.Id, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<Shipment>? shipments;
    private string searchText = "";
    private string statusFilter = "";

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(searchText)
                || s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase)
                || s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            && (string.IsNullOrEmpty(statusFilter)
                || s.Status.ToString() == statusFilter));

    protected override async Task OnInitializedAsync()
    {
        await RefreshAsync();
    }

    private async Task RefreshAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatusAsync(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            await RefreshAsync();
        }
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>📋 Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-100001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchAsync" disabled="@isSearching">
                @if (isSearching) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Search
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number "<strong>@lastSearched</strong>".
        Please verify the number and try again.
    </div>
}
else if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-primary text-white">
            <h4 class="mb-0">Shipment @shipment.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadge(shipment.Status) fs-6">@shipment.Status</span></dd>

                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>

                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>

                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

                        <dt>Estimated Delivery</dt>
                        <dd class="@(shipment.EstimatedDelivery < DateTime.UtcNow && shipment.Status != ShipmentStatus.Delivered ? "text-danger fw-bold" : "")">
                            @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")
                            @if (shipment.Status != ShipmentStatus.Delivered)
                            {
                                var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                                <span class="text-muted">(@(daysLeft > 0 ? $"in {daysLeft} days" : "overdue"))</span>
                            }
                        </dd>

                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd class="text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                        }

                        <dt>Weight</dt>
                        <dd>@shipment.WeightKg kg</dd>
                    </dl>
                </div>
            </div>
            @if (!string.IsNullOrWhiteSpace(shipment.Notes))
            {
                <div class="alert alert-light mt-3">
                    <strong>Notes:</strong> @shipment.Notes
                </div>
            }

            <!-- Visual progress indicator -->
            <h5 class="mt-4">Delivery Progress</h5>
            @{ var progressSteps = GetProgressSteps(shipment.Status); }
            <div class="d-flex justify-content-between mt-3">
                @foreach (var (label, active) in progressSteps)
                {
                    <div class="text-center" style="flex:1">
                        <div class="rounded-circle mx-auto d-flex align-items-center justify-content-center @(active ? "bg-primary text-white" : "bg-light text-muted border")"
                             style="width:40px;height:40px;">
                            @(active ? "✓" : "○")
                        </div>
                        <small class="@(active ? "fw-bold" : "text-muted")">@label</small>
                    </div>
                }
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string lastSearched = "";
    private Shipment? shipment;
    private bool searched;
    private bool isSearching;

    private async Task SearchAsync()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        lastSearched = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        searched = true;
        isSearching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchAsync();
    }

    private static List<(string Label, bool Active)> GetProgressSteps(ShipmentStatus status)
    {
        var steps = new List<(string, bool)>
        {
            ("Pending", status >= ShipmentStatus.Pending),
            ("Picked Up", status >= ShipmentStatus.PickedUp),
            ("In Transit", status >= ShipmentStatus.InTransit),
            ("Out for Delivery", status >= ShipmentStatus.OutForDelivery),
            ("Delivered", status >= ShipmentStatus.Delivered)
        };
        return steps;
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

